mapper.select:
select distinct A.PORTFOLIO_ID as portfolioId, C.PROFIT_TYPE as profitType, C.FINPROD_ID as finprodId, C.FINPROD_MARKET_ID as marketId, A.PROD_ID as prodId, A.SETTLE_DATE as cashDate, fpa.SALE_DEPARTMENT as saleDepartment, fpa.DEAL_MODE as dealMode, A.TRADE_DATE as confirmDate, C.CCY as ccy, C.VDATE as prodVdate, fpa.IS_CYCLE as isCycle, fpa.IS_LAY as isLay, sum(CASE WHEN A.PS = #{JYFX_CPRG} THEN IFNULL(A.TRADE_AMT,0) WHEN #{JYFX_CPSG} THEN IFNULL(A.TRADE_AMT,0) ELSE 0 END
) as tdyBuyMoney, sum( CASE WHEN A.PS=#{JYFX_CPRG} THEN IFNULL(A.SHARE_AMT,0) WHEN #{JYFX_CPSG} THEN IFNULL(A.SHARE_AMT,0) ELSE 0 END
) as tdyBuyQty, sum( CASE WHEN A.PS = #{JYFX_CPSH} THEN IFNULL(A.TRADE_AMT,0) WHEN #{JYFX_CPDQ} THEN IFNULL(A.TRADE_AMT,0) WHEN #{JYFX_CPTQZZ} THEN IFNULL(A.TRADE_AMT,0) WHEN #{JYFX_CPWYSH} THEN IFNULL(A.TRADE_AMT,0) WHEN #{JYFX_CPTQSH} THEN IFNULL(A.TRADE_AMT,0) ELSE 0 END
) as tdyRedMoney, sum( CASE WHEN A.PS = #{JYFX_CPSH} THEN IFNULL(A.SHARE_AMT,0) WHEN #{JYFX_CPDQ} THEN IFNULL(A.SHARE_AMT,0) WHEN #{JYFX_CPTQZZ} THEN IFNULL(A.SHARE_AMT,0) WHEN #{JYFX_CPWYSH} THEN IFNULL(A.SHARE_AMT,0) WHEN #{JYFX_CPTQSH} THEN IFNULL(A.SHARE_AMT,0) ELSE 0 END
) as tdyRedQty, sum(IFNULL(A.INT_AMT, 0)) as tdyCarriedInterest, sum( CASE WHEN A.PS = #{JYFX_CPHLZT} THEN IFNULL(A.TRADE_AMT,0) ELSE 0 END
) as tdyCarriedMoney, sum( CASE WHEN A.PS = #{JYFX_CPHLZT} THEN IFNULL(A.SHARE_AMT,0) ELSE 0 END
) as tdyCarriedQty, sum( CASE WHEN A.PS = #{JYFX_FEQZ} THEN IFNULL(A.TRADE_AMT,0) ELSE 0 END
) as tdyForceIncreaseMoney, sum( CASE WHEN A.PS = #{JYFX_FEQZ} THEN IFNULL(A.SHARE_AMT,0) ELSE 0 END
) as tdyForceIncreaseQty, sum(CASE WHEN A.PS = #{JYFX_FEQJ} THEN IFNULL(A.TRADE_AMT,0) ELSE 0 END
) as tdyForceReduceMoney, sum( CASE WHEN A.PS = #{JYFX_FEQJ} THEN IFNULL(A.SHARE_AMT,0) ELSE 0 END
) as tdyForceReduceQty ,A.TOTLE_TRADE_ID as tradeId from TRD_FIN_PRODUCT_DEAL_TOTAL A inner join FIN_PRODUCT C on A.FINPROD_ID = C.FINPROD_ID and C.PROFIT_TYPE = #{PROFIT_TYPE_SY} left join FIN_PRODUCT_ADD fpa on C.FINPROD_ID = fpa.FINPROD_ID left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL B on A.TOTLE_TRADE_ID = B.TOTLE_TRADE_ID left join PA_FIN_PRODUCT PFP on C.FINPROD_ID = PFP.FINPROD_ID where C.FINPROD_TYPE2 = #{FINPROD_TYPE2_LCCP}
and A.PS not in (#{JYFX_CPCQDJ},#{JYFX_CPFF},#{JYFX_SFJN})
and A.TRADE_STATUS = #{TRADE_STATUS_CS} and A.IS_CANCEL = #{YES_NO_N}
AND A.PORTFOLIO_ID IN
#{item}
AND A.FINPROD_ID IN
#{item}
AND fpa.DEAL_MODE = #{dealMode}
AND A.SETTLE_DATE >= str_to_date(#{cashDateBegin}, '%Y-%m-%d')
AND A.SETTLE_DATE <= str_to_date(#{cashDateEnd}, '%Y-%m-%d')
AND A.TRADE_DATE >= str_to_date(#{confirmDateBegin}, '%Y-%m-%d')
AND A.TRADE_DATE <= str_to_date(#{confirmDateEnd}, '%Y-%m-%d')
and A.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})
AND A.PS = #{dealType}
AND C.CCY = #{ccy}
AND fpa.PROD_MANAGER IN
#{item}
group by A.PORTFOLIO_ID, C.PROFIT_TYPE,C.FINPROD_ID, C.FINPROD_MARKET_ID, A.PROD_ID, A.TRADE_DATE, fpa.SALE_DEPARTMENT, C.CCY, C.VDATE, fpa.IS_LAY, fpa.IS_CYCLE, fpa.DEAL_MODE, A.SETTLE_DATE,A.TOTLE_TRADE_ID
union all
select distinct A.PORTFOLIO_ID as portfolioId, C.PROFIT_TYPE as profitType, C.FINPROD_ID as finprodId, C.FINPROD_MARKET_ID as marketId, A.PROD_ID as prodId, A.SETTLE_DATE as cashDate, fpa.SALE_DEPARTMENT as saleDepartment, fpa.DEAL_MODE as dealMode, A.TRADE_DATE as confirmDate, C.CCY as ccy, C.VDATE as prodVdate, fpa.IS_CYCLE as isCycle, fpa.IS_LAY as isLay, sum(CASE WHEN A.PS = #{JYFX_CPRG} THEN A.TRADE_AMT WHEN #{JYFX_CPSG} THEN A.TRADE_AMT ELSE 0 END
) as tdyBuyMoney, sum(CASE WHEN A.PS = #{JYFX_CPRG} THEN A.SHARE_AMT WHEN #{JYFX_CPSG} THEN A.SHARE_AMT ELSE 0 END
) as tdyBuyQty, sum( CASE WHEN A.PS = #{JYFX_CPSH} THEN A.TRADE_AMT WHEN #{JYFX_CPDQ} WHEN A.TRADE_AMT WHEN #{JYFX_CPTQZZ} THEN A.TRADE_AMT WHEN #{JYFX_CPWYSH} THEN A.TRADE_AMT WHEN #{JYFX_CPTQSH} THEN A.TRADE_AMT ELSE 0 END
) as tdyRedMoney, sum(CASE WHEN A.PS = #{JYFX_CPSH} THEN A.SHARE_AMT WHEN #{JYFX_CPDQ} THEN A.SHARE_AMT WHEN #{JYFX_CPTQZZ} THEN A.SHARE_AMT WHEN #{JYFX_CPWYSH} THEN A.SHARE_AMT WHEN #{JYFX_CPTQSH} THEN A.SHARE_AMT ELSE 0 END
) as tdyRedQty, sum( CASE WHEN A.PS = #{JYFX_CPXJFH} THEN A.TRADE_AMT ELSE 0 END
) as tdyCarriedInterest, sum(CASE WHEN A.PS = #{JYFX_CPHLZT} THEN A.TRADE_AMT ELSE 0 END
) as tdyCarriedMoney, sum(CASE WHEN A.PS = #{JYFX_CPHLZT} THEN A.SHARE_AMT ELSE 0 END
) as tdyCarriedQty, sum(CASE WHEN A.PS = #{JYFX_FEQZ} THEN A.TRADE_AMT ELSE 0 END
) as tdyForceIncreaseMoney, sum(CASE WHEN A.PS = #{JYFX_FEQZ} THEN A.SHARE_AMT ELSE 0 END
) as tdyForceIncreaseQty, sum(CASE WHEN A.PS = #{JYFX_FEQJ} WHEN A.TRADE_AMT ELSE 0 END
) as tdyForceReduceMoney, sum(CASE WHEN A.PS WHEN #{JYFX_FEQJ} THEN A.SHARE_AMT ELSE 0 END
) as tdyForceReduceQty ,A.TOTLE_TRADE_ID as tradeId from TRD_FIN_PRODUCT_DEAL_TOTAL A inner join FIN_PRODUCT C on A.FINPROD_ID = C.FINPROD_ID and C.PROFIT_TYPE <> #{PROFIT_TYPE_SY} left join FIN_PRODUCT_ADD fpa on C.FINPROD_ID = fpa.FINPROD_ID left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL B on A.TOTLE_TRADE_ID = B.TOTLE_TRADE_ID left join PA_FIN_PRODUCT PFP on C.FINPROD_ID = PFP.FINPROD_ID where C.FINPROD_TYPE2 = #{FINPROD_TYPE2_LCCP}
and A.PS not in (#{JYFX_CPCQDJ},#{JYFX_CPFF},#{JYFX_SFJN})
and A.TRADE_STATUS = #{TRADE_STATUS_CS} and A.IS_CANCEL = #{YES_NO_N}
AND A.PORTFOLIO_ID IN
#{item}
AND A.FINPROD_ID IN
#{item}
AND fpa.DEAL_MODE = #{dealMode}
AND A.SETTLE_DATE >= str_to_date(#{cashDateBegin}, '%Y-%m-%d')
AND A.SETTLE_DATE <= str_to_date(#{cashDateEnd}, '%Y-%m-%d')
AND A.TRADE_DATE >= str_to_date(#{confirmDateBegin}, '%Y-%m-%d')
AND A.TRADE_DATE <= str_to_date(#{confirmDateEnd}, '%Y-%m-%d')
and A.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})
AND A.PS = #{dealType}
AND fpa.PROD_MANAGER IN
#{item}
AND C.CCY = #{ccy}
group by A.PORTFOLIO_ID, C.PROFIT_TYPE,C.FINPROD_ID, C.FINPROD_MARKET_ID, A.PROD_ID, A.TRADE_DATE, fpa.SALE_DEPARTMENT, C.CCY, C.VDATE, fpa.IS_LAY, fpa.IS_CYCLE, fpa.DEAL_MODE, A.SETTLE_DATE,A.TOTLE_TRADE_ID
order by portfolioId, finprodId, prodId, cashDate

select A.PORTFOLIO_ID as portfolioId, A.FINPROD_ID as finprodId, A.PROD_ID as prodId, A.SETTLE_DATE as cashDate, A.PS as ps, A.SHARE_AMT as shareAmout, B.THEORY_PRIN as mPrin from TRD_FIN_PRODUCT_DEAL_TOTAL A left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL B on A.TOTLE_TRADE_ID = B.TOTLE_TRADE_ID where A.FINPROD_TYPE2 = #{FINPROD_TYPE2_LCCP} and A.TRADE_STATUS = #{TRADE_STATUS_CS} and A.IS_CANCEL = #{YES_NO_N} AND IFNULL(A.P_TRADE_ID, 'null') = 'null'
AND A.PORTFOLIO_ID IN
#{item}
AND A.FINPROD_ID IN
#{item}
AND A.FINPROD_ID IN
#{item}
AND A.SETTLE_DATE <= STR_TO_DATE(#{cashDateEnd}, '%Y-%m-%d')
order by A.PORTFOLIO_ID, A.FINPROD_ID, A.PROD_ID, A.TRADE_DATE

select A.FINPROD_ID as finprodId, A.EFF_DATE as effDate, A.YIELD as yield, B.P_FINPROD_ID as pFinprodId from FIN_CASH_CALC_RULE A inner join FIN_PRODUCT B on A.FINPROD_ID = B.FINPROD_ID
inner join FIN_CASH_INFO C on A.CASH_ID = C.CASH_ID
where
A.FINPROD_TYPE2 in ( #{FINPROD_TYPE2_LCCP}, #{FINPROD_TYPE2_LCCPFD})
AND A.EFF_DATE <= STR_TO_DATE(#{cashDateEnd}, '%Y-%m-%d')
AND C.CASH_TYPE_1 = #{CASH_TYPE_1_LX} AND C.CASH_TYPE_2 = #{CASH_TYPE_2_LX}
AND A.FINPROD_ID in ( select FINPROD_ID from FIN_PRODUCT where PROFIT_TYPE = #{PROFIT_TYPE_SY} and (P_FINPROD_ID is null or P_FINPROD_ID = '')
AND FINPROD_ID IN
#{item}
union all select FINPROD_ID from FIN_PRODUCT where PROFIT_TYPE = #{PROFIT_TYPE_SY}
and (P_FINPROD_ID is not null or P_FINPROD_ID != '')
AND P_FINPROD_ID IN
#{item}
) order by B.P_FINPROD_ID, A.FINPROD_ID, A.EFF_DATE

select B.FINPROD_ID as finprodId, A.CDATE as cdate, CASE B.PROFIT_TYPE WHEN #{PROFIT_TYPE_SY} THEN A.TDY_YIELD ELSE A.TDY_UNIT_VALUE END tdyYield from Bok_Position_Prd A LEFT JOIN FIN_PRODUCT B ON A.FINPROD_ID = B.FINPROD_ID
1=1
AND A.CDATE >= str_to_date(#{cashDateBeginEarly}, '%Y-%m-%d')
AND A.CDATE <= str_to_date(#{cashDateEnd}, '%Y-%m-%d')
AND B.PROFIT_TYPE != #{PROFIT_TYPE_SY}
AND B.FINPROD_MARKET_ID IN
#{item}
AND B.FINPROD_ID IN
#{item}
order by B.FINPROD_ID, A.CDATE

select A.FINPROD_ID as finprodId, A.VAL_DATE as valDate, A.VALUATION as valuation from FIN_PRODUCT_VALUATION A
A.FINPROD_TYPE2 = #{FINPROD_TYPE2_LCCP}
AND A.VAL_DATE >= STR_TO_DATE(#{cashDateBeginEarly}, '%Y-%m-%d')
AND A.VAL_DATE <= STR_TO_DATE(#{cashDateEnd}, '%Y-%m-%d')
AND A.FINPROD_ID in ( select FINPROD_ID from FIN_PRODUCT where PROFIT_TYPE != #{PROFIT_TYPE_SY}
AND FINPROD_MARKET_ID IN
#{item}
AND FINPROD_ID IN
#{item}
)
order by A.FINPROD_ID, A.VAL_DATE
